/* Scholarion integrated local prototype. Role switching is a demo, not authorization. */
const STORE_KEY='scholarion-demo-v2';
const freshModel=()=>({version:2,role:'learner',enrollments:[],drafts:[],reviews:{},hidden:[],audit:[],capstone:null,readiness:[],practice:null});
let model=freshModel();
try{const saved=JSON.parse(localStorage.getItem(STORE_KEY)||'null');if(saved?.version===2&&['enrollments','drafts','hidden','audit','readiness'].every(k=>Array.isArray(saved[k]))&&saved.reviews&&typeof saved.reviews==='object')model={...model,...saved};}catch{}
if(model.practice){const p=model.practice;state.completed=new Set(p.completed||[]);state.quizIndex=Number.isInteger(p.quizIndex)&&p.quizIndex>=0&&p.quizIndex<3?p.quizIndex:0;state.answers=p.answers||{};state.quizSubmitted=!!p.quizSubmitted;state.labSubmitted=!!p.labSubmitted;state.labCode=typeof p.labCode==='string'?p.labCode:state.labCode;state.project=p.project||null;state.discussion=Array.isArray(p.discussion)?p.discussion:[];}
let storageWarning=false;
function persist(){model.practice={completed:[...state.completed],quizIndex:state.quizIndex,answers:state.answers,quizSubmitted:state.quizSubmitted,labSubmitted:state.labSubmitted,labCode:state.labCode,project:state.project,discussion:state.discussion};try{localStorage.setItem(STORE_KEY,JSON.stringify(model));}catch{if(!storageWarning){storageWarning=true;toast('Device storage is unavailable. Changes will last for this session only.');}}}
function audit(action){model.audit.unshift({time:new Date().toISOString(),role:model.role,action});model.audit=model.audit.slice(0,100);persist();}
const findProgram=id=>programCatalog.find(p=>p.id===Number(id));
const listHTML=xs=>`<ul>${xs.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`;
const portalRender=render;
const homepageRender=landing;
landing=function(){return homepageRender().replaceAll('href="#programs"','href="#catalog"').replace('href="#about">'+icon('chart')+'LMS Overview','href="#lms">'+icon('chart')+'LMS Overview').replace('data-action="program-catalog"','data-integrated="catalog"').replace('11 Certificate Programs<br>','11 Core Certificate Programs<br>').replace('Design preview · Proposed program catalog and services · Enrollment is not yet open','Design preview · 11 core programs + extended pathways · Enrollment is not yet open');};
let filter={query:'',track:'All',format:'All',level:'All'},compare=new Set();
const roleNav={faculty:[['faculty','home','Faculty overview'],['studio','file','Scholarion Studio'],['grading','chart','Grading workspace'],['faculty/learners','book','Learners & outcomes'],['catalog','folder','Program catalog'],['pathways','award','Pathways'],['dashboard','book','Student preview']],admin:[['admin','home','Admin overview'],['admin/catalog','folder','Catalog control'],['admin/roles','shield','Roles & permissions'],['admin/credentials','award','Credential workflow'],['admin/audit','file','Audit history'],['admin/settings','help','Settings & data'],['pathways','globe','Pathways']]};
function integratedShell(route,body,role=model.role){let html=shell(route,body);return html.replace('Interactive preview · Sample learner data · Changes last until refresh','Local demo · Saved on this browser · No live accounts').replace('<a href="#about">About this demo</a>','<a href="#signin">Switch workspace</a>').replace('Amara Chukwu</b>',''+(role==='faculty'?'Faculty preview':role==='admin'?'Administrator preview':'Amara Chukwu')+'</b>').replace('Demo learner</small>',(role==='learner'?'Demo learner':'Demo '+role)+'</small>');}
function decorateRole(role){if(!roleNav[role])return;document.querySelector('.sidebar nav').innerHTML=roleNav[role].map(([href,ic,label])=>`<a class="nav-item ${location.hash==='#'+href?'active':''}" href="#${href}">${icon(ic)}${label}</a>`).join('');}
function catalogCards(){const q=filter.query.toLowerCase();const rows=programCatalog.filter(p=>!model.hidden.includes(p.id)&&(!q||`${p.id} ${p.title} ${p.summary}`.toLowerCase().includes(q))&&(filter.track==='All'||p.track===filter.track)&&(filter.format==='All'||(filter.format==='Self-paced'?p.format==='Self-paced':p.format!=='Self-paced'))&&(filter.level==='All'||p.level===filter.level));return `<div class="between section-title"><p class="muted" role="status">${rows.length} program${rows.length===1?'':'s'} · Curriculum previews</p><button class="button secondary small" data-integrated="compare">Compare selected (${compare.size}/3)</button></div><div class="catalog-grid">${rows.map(p=>`<article class="card catalog-card"><div class="between"><span class="eyebrow muted">PROGRAM ${p.id} · ${esc(p.track)}</span><label class="compare-control"><input type="checkbox" data-compare="${p.id}" ${compare.has(p.id)?'checked':''} aria-label="Compare program ${p.id}"> Compare</label></div><h2>${esc(p.title)}</h2><div class="row wrap"><span class="tag">${esc(p.level)}</span><span class="tag">${esc(p.length)}</span></div><p>${esc(p.summary||p.title)}</p><div class="catalog-meta">${esc(p.format)}<br>${esc(p.coding)}</div>${btn('View program',`#program/${p.id}`,true)}</article>`).join('')||'<div class="card empty"><h2>No matching programs</h2><p>Try another search or clear the filters.</p></div>'}</div>`;}
function catalogPage(){return '<p><a class="button secondary" href="#self-paced">Explore self-paced courses and certificates</a> <a href="#agentic-catalog">Publication-approved catalog</a></p>'+heading('Find your next chapter.','35 source-backed program previews · Original IDs preserved',btn('Explore pathways','#pathways',true))+`<div class="filterbar card"><label>Search programs<input id="catalog-query" type="search" value="${esc(filter.query)}" placeholder="Try agents, healthcare, or program 12"></label><label>Track<select id="catalog-track">${['All',...new Set(programCatalog.map(p=>p.track))].map(x=>`<option ${x===filter.track?'selected':''}>${esc(x)}</option>`).join('')}</select></label><label>Format<select id="catalog-format">${['All','Live / cohort','Self-paced'].map(x=>`<option ${x===filter.format?'selected':''}>${x}</option>`).join('')}</select></label><label>Level<select id="catalog-level">${['All','Foundational','Intermediate','Advanced'].map(x=>`<option ${x===filter.level?'selected':''}>${x}</option>`).join('')}</select></label><button class="button ghost" data-integrated="clear-filters">Clear</button></div><div class="catalog-note">Program outlines are imported from your supplied specifications. Fees, cohort dates, and enrollment are not configured. Programs 13 and 14 lack specifications; 27 remains proposed.</div><div id="catalog-results">${catalogCards()}</div>`;}
function curriculum(p){if(p.weeks?.length)return `<div class="module-list">${p.weeks.map(([week,text])=>`<div class="module-row"><span class="module-number">${esc(week)}</span><div><h3>${esc(text)}</h3><p>Curriculum outline · lesson materials pending review</p></div></div>`).join('')}</div>`;if(p.specification)return `<div class="source-outline">${p.specification.split('\n').filter(l=>l.trim()&&!l.startsWith('#')).map(l=>`<p>${esc(l)}</p>`).join('')}</div>`;return '<p class="muted">The supplied record defines the program and capstone. A detailed module sequence has not yet been supplied.</p>';}
function programPage(id){const p=findProgram(id);if(!p)return heading('Program specification unavailable','This program is not included in the supplied catalog.',btn('Back to catalog','#catalog'));return `<div class="breadcrumbs"><a href="#catalog">Program catalog</a><span>/</span><span>Program ${p.id}</span></div><section class="program-banner"><div class="eyebrow">SCHOLARION AI ACADEMY · ${esc(p.track)}</div><h1>${esc(p.title)}</h1><p>${esc(p.summary)}</p><div class="row wrap"><span class="tag">${esc(p.length)}</span><span class="tag">${esc(p.format)}</span><span class="tag">${esc(p.level)}</span></div></section><div class="two-col" style="margin-top:25px"><article class="card prose"><h2>Your learning journey</h2>${p.outcomes?listHTML(p.outcomes):`<p>${esc(p.summary)}</p>`}<h3>Curriculum</h3>${curriculum(p)}<hr class="divider"><h2>Capstone project</h2><p>${esc(p.capstone)}</p>${p.projects?listHTML(p.projects.map(x=>`${x.name}: ${x.description}`)):''}<h3>Scenario-based learning</h3><p>Scenario → Learn → Practice → Mini Lab → Scenario Quiz → Mini Project → Project Milestone → Feedback → Capstone.</p><p>Detailed activity content is being developed. The Python Module 5 walkthrough demonstrates this pattern.</p>${btn('Explore a complete sample module','#module',true)}</article><aside class="stack program-aside"><div class="card prose"><h2>Program facts</h2><p><b>Duration</b><br>${esc(p.length)}</p><p><b>Coding</b><br>${esc(p.coding)}</p>${p.workload?`<p><b>Weekly effort</b><br>${esc(p.workload)}</p>`:''}<p><b>Prerequisites</b><br>${esc(p.prerequisites||p.coding)}</p><p><b>Credential</b><br>Certificate of completion · Non-credit professional learning</p><button class="button" data-enroll="${p.id}" ${model.enrollments.includes(p.id)?'disabled':''}>${model.enrollments.includes(p.id)?'Added to my demo learning':'Add to my demo learning'}</button><p style="font-size:.75rem">Saves locally. This is not enrollment or payment.</p><button class="button secondary" data-syllabus="${p.id}">Download outline</button></div><div class="card prose"><h3>Completion requirements</h3><p>${esc(p.requirements||'Required learning activities, assessments, and capstone review. Final criteria are pending curriculum approval.')}</p><a class="text-link" href="#pathways">See stackable pathways</a></div>${p.stacking?`<div class="card prose"><h3>Proposed stacking</h3><p>${esc(p.stacking)}</p><p>Subject to curriculum review. No automatic credit is awarded in this preview.</p></div>`:''}</aside></div>`;}
const pathsData=[['AI Foundations to Agentic Engineering',[21,18,19,16,15],'Program 1 is an alternative to 15; the overlapping content is not counted twice.'],['GenAI Builder',[19,2,17],'Build prompting and application skills before the extended pathway.'],['No-Code Professional',[7,6,5],'Progress from everyday productivity to workflows and predictive systems.'],['Data & AI Platforms',[21,22,27],'Program 27 is proposed and is not available for enrollment.'],['Product & Leadership',[20,12,23,13,25],'Programs 12 and 23 have distinct design and product-management focuses; overlapping learning needs review. Program 13 is missing its source specification.'],['Self-Paced Agent Builder',[32,35,30,31,33,28],'Programs 30 and 31 overlap. Proposed waivers require a recorded review.']];
function pathways(){return heading('Build on what you know.','Explore proposed sequences and transparent transfer rules.')+`<div class="stack">${pathsData.map(([title,ids,note])=>`<section class="card"><h2>${title}</h2><div class="pathway-flow">${ids.map(id=>{const p=findProgram(id);return p?`<a class="pathway-node" href="#program/${id}"><span class="eyebrow">PROGRAM ${id}</span><h3>${esc(p.title)}</h3><span>${esc(p.length)}</span></a>`:`<div class="pathway-node pending"><span class="eyebrow">PROGRAM ${id}</span><h3>${id===27?'MLOps & LLMOps · Proposed':'Specification needed'}</h3><span>Not available</span></div>`}).join('<span class="pathway-arrow" aria-hidden="true">→</span>')}</div><p class="muted" style="font-size:.875rem">${note}</p></section>`).join('')}<section class="card prose"><h2>Transfer is a review, not a promise.</h2><p>Source documents propose module reuse and waivers, including Program 16 into 15, and Program 26 into parts of 15. Some source versions disagree on the exact scope. These remain proposals until an educator confirms equivalent outcomes and evidence.</p></section></div>`;}
function loginPage(){return `<main class="integrated-login"><section class="login-story"><a class="welcome-brand" href="#home" aria-label="Scholarion homepage"><img src="assets/scholarion-welcome-logo.png" alt="Scholarion — Learn. Earn. Build Your Future. A Global Learning Platform." width="2048" height="683"></a><div><div class="eyebrow">SCHOLARION GLOBAL LEARNING</div><h1>One platform.<br>Every step of<br>your journey.</h1><p>Learn, practice, build, and demonstrate what you know.</p></div><a href="#home">Back to the academy</a></section><section class="login-form-wrap"><form class="card" id="workspace-form"><span class="tag">Local demo</span><h1 style="margin:18px 0">Welcome back.</h1><p class="muted">Choose a workspace to explore the integrated experience.</p><label class="form-field">Workspace<select name="role"><option value="learner">Learner · Amara Chukwu</option><option value="faculty">Faculty · Teaching workspace</option><option value="admin">Administrator · Academy operations</option></select></label><button class="button" style="width:100%;margin-top:10px">Open workspace</button><p class="muted" style="font-size:.8rem;margin-top:20px">No password is collected. This switch demonstrates roles; it does not provide secure authentication. Demo work is stored only in this browser.</p></form></section></main>`;}
function lmsOverview(){return heading('The complete learning lifecycle.','One Scholarion platform, connected across learners, faculty, and administrators.')+`<div class="course-grid">${[['Learners','Follow modules, practice in labs, submit projects, and review feedback.','dashboard','book'],['Faculty','Author scenario-based modules, publish to the demo, and review submissions.','faculty','file'],['Administrators','Inspect the catalog, proposed pathways, credential readiness, and audit trail.','admin','shield']].map(([t,d,r,i])=>`<section class="card prose"><div class="stat-icon">${icon(i)}</div><h2 style="margin-top:18px">${t}</h2><p>${d}</p>${btn('Explore workspace','#'+r)}</section>`).join('')}</div><div class="card prose" style="margin-top:25px"><h2>Learning connected to practice</h2><p>Scenario → Learn → Practice → Mini Lab → Scenario Quiz → Mini Project → Project Milestone → Feedback → Capstone → Demonstration of mastery.</p><p>This build connects the demo workflow locally. Hosted accounts, verified badges, external labs, and institutional integrations remain unconnected.</p></div>`;}
function facultyPage(section){if(section==='learners')return heading('Learners & outcomes','Sample learner progress and current local activity.')+`<div class="card"><h2>Amara Chukwu · Python Programming</h2><div class="table-scroll"><table><thead><tr><th>Outcome evidence</th><th>Status</th></tr></thead><tbody>${[['Functions lesson',state.completed.has('functions')?'Complete':'Not complete'],['Practice lab',state.labSubmitted?'Submitted':'Not submitted'],['Scenario quiz',state.quizSubmitted?'Completed':'Not completed'],['Mini project',state.project?'Submitted':'Not submitted'],['Capstone',model.capstone?'Submitted':'Not submitted']].map(([a,b])=>`<tr><td>${a}</td><td>${b}</td></tr>`).join('')}</tbody></table></div></div>`;return heading('Your teaching workspace','Build purposeful learning. Give useful feedback.',btn('Create a module','#studio'))+`<div class="stats">${[['file',model.drafts.length,'Authored modules'],['book',model.drafts.filter(d=>d.published).length,'Published to demo'],['chart',submissions().filter(s=>!model.reviews[s.id]).length,'Awaiting review'],['award',Object.keys(model.reviews).length,'Reviewed']].map(([ic,n,l])=>`<div class="stat"><div class="stat-icon">${icon(ic)}</div><div><strong>${n}</strong><span>${l}</span></div></div>`).join('')}</div><div class="two-col"><div class="card prose"><h2>Scholarion Studio</h2><p>Create a workplace scenario, define the activity sequence, and publish a module to the learner preview.</p>${btn('Open Studio','#studio')}</div><div class="card prose"><h2>Grading workspace</h2><p>Read submitted descriptions, score against a rubric, and return feedback to the learner gradebook.</p>${btn('Review submissions','#grading',true)}</div></div><div class="callout">All changes are local demo records. Switching workspaces does not authenticate a different user.</div>`;}
const studioFields=[['title','Module title'],['scenario','Workplace scenario and learner role'],['objectives','Learning objectives'],['lab','Mini lab instructions'],['quiz','Scenario quiz prompt'],['project','Mini project deliverable'],['milestone','Capstone milestone'],['feedback','Review criteria and feedback guidance']];
function studioPage(id){const d=model.drafts.find(d=>d.id===id);return heading('Scholarion Studio','Design a complete scenario-based learning sequence.')+`<div class="two-col"><form class="card" id="studio-form"><h2>${d?'Edit module':'Create a module'}</h2><input type="hidden" name="id" value="${esc(d?.id||'')}">${studioFields.map(([key,label])=>`<label class="form-field">${label}${key==='title'?`<input name="${key}" value="${esc(d?.[key]||'')}" required maxlength="160">`:`<textarea name="${key}" rows="3" required maxlength="5000">${esc(d?.[key]||'')}</textarea>`}</label>`).join('')}<button class="button">Save draft</button></form><aside class="stack"><div class="card prose"><h2>Module library</h2>${model.drafts.length?model.drafts.map(d=>`<div class="module-row"><div><h3>${esc(d.title)}</h3><p>${d.published?'Published in this demo':'Draft'}</p><div class="row wrap"><a class="text-link" href="#studio/${d.id}">Edit</a><button class="text-link" data-publish="${d.id}">${d.published?'Unpublish':'Publish to demo'}</button>${d.published?`<a class="text-link" href="#authored/${d.id}">Learner view</a>`:''}</div></div></div>`).join(''):'<p>No authored modules yet. Create your first scenario-based module.</p>'}</div><div class="card prose"><h3>Publication checklist</h3><p>All eight fields must be complete. Publishing makes the module visible under the learner’s courses in this local demo.</p><p>Quiz prompts are displayed as reflection activities. They are not automatically graded.</p></div></aside></div>`;}
function authoredPage(id){const d=model.drafts.find(d=>d.id===id&&d.published);if(!d)return heading('Module unavailable','This module is still a draft or has been unpublished.',btn('My courses','#courses'));return heading(esc(d.title),'Faculty-authored module · Local learning preview')+`<article class="card prose">${studioFields.slice(1).map(([k,l])=>`<h2>${l}</h2><p style="white-space:pre-wrap">${esc(d[k])}</p>`).join('')}<button class="button" data-authored-complete="${d.id}">${state.completed.has(d.id)?'Marked complete':'Mark reviewed'}</button></article>`;}
function submissions(){const rows=[];if(state.project)rows.push({id:'mini-project',title:'Patient records system',name:state.project.name,notes:state.project.notes});if(model.capstone)rows.push({id:'capstone',title:'Healthcare data analysis',name:model.capstone.name,notes:model.capstone.notes});return rows;}
function gradingPage(){return heading('Feedback that moves learning forward.','Review local demo submissions against the rubric.')+`<div class="stack">${submissions().map(s=>{const review=model.reviews[s.id];return `<form class="card grading-form" data-submission="${s.id}"><div class="between"><div><span class="eyebrow muted">AMARA CHUKWU · PYTHON PROGRAMMING</span><h2 style="margin-top:8px">${s.title}</h2></div><span class="tag ${review?'green':''}">${review?'Reviewed':'Needs review'}</span></div><p class="muted" style="margin:15px 0">${esc(s.name)} · File contents are not uploaded in this demo.</p><div class="callout" style="white-space:pre-wrap">${esc(s.notes)}</div><div class="rubric-grid">${[['correctness','Required features',40],['structure','Code organization',30],['validation','Input validation',20],['explanation','Explanation',10]].map(([key,label,max])=>`<label class="form-field">${label} / ${max}<input type="number" name="${key}" min="0" max="${max}" step="1" value="${review?.scores[key]??''}" required></label>`).join('')}</div><label class="form-field">Feedback to learner<textarea name="feedback" required rows="3" maxlength="5000">${esc(review?.feedback||'')}</textarea></label><button class="button">Save demo review</button><p class="muted" style="font-size:.75rem;margin-top:12px">Score the described sample evidence only. A production review requires access to submitted files.</p></form>`}).join('')||`<div class="card empty"><h2>No submissions to review</h2><p>Submit a mini project or capstone in the learner workspace first.</p><div style="margin-top:20px">${btn('Open learner project','#project')}</div></div>`}</div>`;}
function capstonePage(){return heading('Capstone: Healthcare data analysis','Use a fictional dataset to develop and explain a complete analysis.')+`<div class="two-col"><article class="card prose"><h2>Project blueprint</h2><p><b>Your role:</b> A data analyst helping an operations team understand service demand.</p><p><b>Core challenge:</b> Prepare inconsistent fictional records, calculate summary statistics, and communicate useful findings without making clinical decisions.</p><h3>Deliverables</h3>${listHTML(['A Python analysis organized into reusable functions.','A data-quality report explaining missing and invalid values.','Summary statistics and an optional visualization.','A short report describing findings, limitations, and responsible use.'])}<h3>Project milestones</h3><div class="checklist">${['Proposal and dataset','Data preparation','Analysis and development','Final report and demonstration'].map((x,i)=>`<label><input type="checkbox" data-milestone="${i}" ${state.completed.has('milestone-'+i)?'checked':''}>${x}</label>`).join('')}</div><button class="button secondary" data-integrated="dataset">Download synthetic CSV</button></article><aside><form class="card" id="capstone-form"><h2>Submit for demo review</h2><label class="form-field">Deliverable filename<input name="name" required placeholder="healthcare-analysis.zip" maxlength="150"></label><label class="form-field">Project summary and evidence<textarea name="notes" rows="7" required maxlength="5000" placeholder="Describe what you built, validation checks, findings, and limitations."></textarea></label><button class="button">Submit demo capstone</button><p class="muted" style="font-size:.75rem;margin-top:15px">Saves the filename and description locally. No file is uploaded.</p>${model.capstone?`<div class="feedback">Current submission: ${esc(model.capstone.name)}</div>`:''}</form></aside></div>`;}
const readinessItems=['Current government-issued photo ID ready','Webcam can show face, hands, and workspace','Microphone is working','Unapproved devices removed; no music','No smart glasses','Assistive technology requirements reviewed through accommodations','Appropriate attire','System check completed'];
function readinessPage(){return heading('Proctored assessment setup','Prepare for test day with the supplied sample policy.')+`<div class="stats readiness-stats">${[['shield','Valid ID','Current photo identification'],['help','Webcam view','Face, hands, and workspace'],['lab','Testing area','Remove unapproved devices']].map(([ic,t,d])=>`<div class="stat"><div class="stat-icon">${icon(ic)}</div><div><h3>${t}</h3><span>${d}</span></div></div>`).join('')}</div><div class="two-col"><section class="card"><h2>Pre-test readiness checklist</h2><div class="checklist">${readinessItems.map((t,i)=>`<label><input type="checkbox" data-proctor="${i}" ${model.readiness.includes(i)?'checked':''}>${t}</label>`).join('')}</div><button class="button" data-integrated="save-readiness">Save readiness check</button><p class="muted" style="margin-top:15px;font-size:.8rem">No camera, microphone, or ID is accessed. These are self-reported checks.</p><div id="readiness-status" role="status"></div></section><aside class="stack"><div class="card prose"><h2>Setup support</h2><p>Choose a topic for guidance from the supplied policy.</p><div class="row wrap">${['Webcam','ID','Devices','Highlighting','Accessibility'].map(t=>`<button class="button secondary small" data-support-topic="${t}">${t}</button>`).join('')}</div><div id="support-answer" class="callout" aria-live="polite">This helper provides fixed setup guidance. It cannot grant exceptions or discuss assessment content or incident decisions.</div></div><div class="card prose"><h3>Accessibility and accommodations</h3><p>Request a review before test day if the setup conflicts with assistive technology. Do not enter diagnoses or medical details here.</p><p>Institutional support contacts and final assessment policies are not configured yet.</p></div></aside></div>`;}
function adminPage(section='overview'){if(section==='catalog')return heading('Catalog control','Local preview visibility only; no public publishing occurs here.')+`<div class="card table-scroll"><table><thead><tr><th>ID</th><th>Program</th><th>Source status</th><th>Visible in preview</th></tr></thead><tbody>${programCatalog.map(p=>`<tr><td>${p.id}</td><td><a class="text-link" href="#program/${p.id}">${esc(p.title)}</a></td><td><span class="tag">Draft curriculum</span></td><td><label><input type="checkbox" data-visibility="${p.id}" ${model.hidden.includes(p.id)?'':'checked'} aria-label="Show program ${p.id}"> Visible</label></td></tr>`).join('')}</tbody></table></div>`;if(section==='roles')return heading('Roles & permissions','Proposed role model · Informational, not security enforcement')+`<div class="card table-scroll"><table><thead><tr><th>Capability</th><th>Learner</th><th>Faculty</th><th>Administrator</th></tr></thead><tbody>${[['Read assigned content','Yes','Yes','Yes'],['Submit own work','Yes','Student preview','Student preview'],['Author modules','No','Yes','Yes'],['Review submissions','No','Assigned courses','Yes'],['Manage catalog','No','No','Yes'],['Issue official credentials','Not connected','Not connected','Not connected']].map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table><p class="muted" style="margin-top:20px">Production access requires authenticated identities and server-side authorization. Local role selection provides neither.</p></div>`;if(section==='audit')return heading('Audit history','Actions taken in this local demo.')+`<div class="card table-scroll"><table><thead><tr><th>Time</th><th>Workspace</th><th>Action</th></tr></thead><tbody>${model.audit.map(x=>`<tr><td>${esc(new Date(x.time).toLocaleString())}</td><td>${esc(x.role)}</td><td>${esc(x.action)}</td></tr>`).join('')||'<tr><td colspan="3">No actions recorded yet.</td></tr>'}</tbody></table></div>`;if(section==='credentials'){const checks=[['Functions lesson complete',state.completed.has('functions')],['Practice lab submitted',state.labSubmitted],['Practice quiz ≥ 70%',state.quizSubmitted&&questions.filter((q,i)=>state.answers[i]===q.answer).length===3],['Mini project reviewed ≥ 70%',model.reviews['mini-project']?.total>=70],['Capstone reviewed ≥ 70%',model.reviews.capstone?.total>=70]];return heading('Credential readiness','Demonstration of requirements validation · No real credentials are issued')+`<div class="two-col"><div class="card"><h2>Amara · Sample learning workflow</h2>${checks.map(([label,done])=>`<div class="module-row"><span class="module-number">${done?icon('check'):'·'}</span><span>${label}</span><span class="tag ${done?'green':''}">${done?'Met':'Pending'}</span></div>`).join('')}<div class="callout">${checks.every(x=>x[1])?'Demo evidence is ready for an educator review.':'Complete the pending demo evidence before educator review.'} Actual program eligibility requires its full curriculum and verified records.</div>${btn('View sample certificate','#credentials',true)}</div><div class="card prose"><h2>Credential workflow</h2>${listHTML(['Completion event','Requirements validation','Faculty or program approval','Personalized certificate and badge','Credential ID and verification service','Learner wallet and delivery','Audit record'])}<p>Badge signing, QR verification, email delivery, and external verification remain unconnected.</p></div></div>`;}if(section==='settings')return heading('Demo data settings','Your work is stored in this browser only.')+`<div class="card prose"><h2>Keep a copy of your work</h2><p>Export includes authored modules, practice answers, submission descriptions, reviews, readiness checks, and the local audit history.</p><div class="row wrap"><button class="button" data-integrated="export">Export demo data</button><button class="button secondary" data-integrated="reset-prompt">Reset local demo</button></div><p>No passwords, API keys, or identity documents are collected.</p></div>`;return heading('Scholarion administration','A connected view of the academy’s local demo.')+`<div class="stats">${[['folder',programCatalog.length,'Program specifications'],['book',model.enrollments.length,'Demo learning selections'],['file',model.drafts.length,'Authored modules'],['shield',model.audit.length,'Recorded actions']].map(([i,n,t])=>`<div class="stat"><div class="stat-icon">${icon(i)}</div><div><strong>${n}</strong><span>${t}</span></div></div>`).join('')}</div><div class="course-grid">${[['Catalog control','Manage which imported programs appear in the preview.','catalog'],['Credential readiness','Inspect required evidence and educator review status.','credentials'],['Audit history','Review changes made across workspaces.','audit']].map(([t,d,r])=>`<div class="card prose"><h2>${t}</h2><p>${d}</p>${btn('Open','#admin/'+r,true)}</div>`).join('')}</div><div class="card prose" style="margin-top:25px"><h2>Source reconciliation</h2><p>35 programs imported. Programs 13 and 14 have no supplied standalone specification. Program 27 remains a proposal. The public cover retains the 11 core offerings; the full catalog includes extended and self-paced pathways.</p><p>All curriculum records are drafts. Tool versions, licenses, teaching materials, and final program requirements still need review before a live launch.</p></div>`;}
function extraCourses(){return `<section class="card" style="margin-top:25px"><div class="between"><h2>My program previews</h2><a class="text-link" href="#catalog">Browse catalog</a></div>${model.enrollments.length?model.enrollments.map(id=>findProgram(id)).filter(Boolean).map(p=>`<a href="#program/${p.id}" class="module-row"><span class="module-number">${p.id}</span><div><h3>${esc(p.title)}</h3><p>${esc(p.length)} · Curriculum preview</p></div></a>`).join(''):'<p class="muted" style="margin-top:15px">Add a program from the catalog to keep it here.</p>'}</section><section class="card" style="margin-top:25px"><h2>Faculty-published modules</h2>${model.drafts.filter(d=>d.published).map(d=>`<a class="module-row" href="#authored/${d.id}"><span class="module-number">${icon('book')}</span><div><h3>${esc(d.title)}</h3><p>${state.completed.has(d.id)?'Reviewed':'Ready to explore'}</p></div></a>`).join('')||'<p class="muted" style="margin-top:15px">Modules published in Scholarion Studio will appear here.</p>'}</section>`;}
function reviewResults(){return Object.entries(model.reviews).map(([id,r])=>`<section class="card" style="margin-top:20px"><div class="between"><h2>${id==='capstone'?'Capstone':'Mini project'} · Faculty feedback</h2><span class="tag green">${r.total}/100 · Demo review</span></div><p style="white-space:pre-wrap;margin-top:18px">${esc(r.feedback)}</p></section>`).join('');}
render=function(){const [route,part]=location.hash.slice(1).split('/');let body,role=['authored','capstone','assessment','proctor'].includes(route)?'learner':model.role;if(route==='signin'){document.getElementById('app').innerHTML=loginPage();bindIntegrated();return;}if(route==='catalog'||route==='program-track'){if(route==='program-track')filter.track=['Builder','No-Code','Business & Leadership','Industry'][Number(part)]||'All';body=catalogPage();}else if(route==='program')body=programPage(part);else if(route==='pathways')body=pathways();else if(route==='lms')body=lmsOverview();else if(route==='faculty'){role='faculty';body=facultyPage(part);}else if(route==='studio'){role='faculty';body=studioPage(part);}else if(route==='grading'){role='faculty';body=gradingPage();}else if(route==='admin'){role='admin';body=adminPage(part);}else if(route==='authored')body=authoredPage(part);else if(route==='capstone')body=capstonePage();else if(route==='assessment'||route==='proctor')body=readinessPage();if(body!==undefined){model.role=role;document.getElementById('app').innerHTML=integratedShell(route,body,role);decorateRole(role);document.title=(document.querySelector('main h1')?.textContent||'Academy')+' · Scholarion';bind();}else{portalRender();const bar=document.querySelector('.demo-bar');if(bar)bar.innerHTML='<span>Local demo · Saved on this browser · No live accounts</span><a href="#signin">Switch workspace</a>';if(['dashboard','courses','module','lab','quiz','project','grades','credentials'].includes(route)){model.role='learner';if(route==='courses')document.querySelector('main').insertAdjacentHTML('beforeend',extraCourses());if(route==='grades')document.querySelector('main').insertAdjacentHTML('beforeend',reviewResults());}const nav=document.querySelector('.sidebar nav');if(nav)nav.insertAdjacentHTML('beforeend','<div class="nav-label">EXPLORE THE ACADEMY</div><a class="nav-item" href="#catalog">'+icon('folder')+'Program catalog</a><a class="nav-item" href="#pathways">'+icon('globe')+'Learning pathways</a><a class="nav-item" href="#signin">'+icon('shield')+'Switch workspace</a>');}bindIntegrated();};
function bindCompare(){document.querySelectorAll('[data-compare]').forEach(el=>el.onchange=()=>{const id=Number(el.dataset.compare);if(el.checked&&compare.size>=3){el.checked=false;return toast('Choose up to three programs.');}el.checked?compare.add(id):compare.delete(id);document.querySelector('[data-integrated="compare"]').textContent=`Compare selected (${compare.size}/3)`;});}
function bindIntegrated(){bindCompare();for(const [id,key] of [['catalog-query','query'],['catalog-track','track'],['catalog-format','format'],['catalog-level','level']]){const el=document.getElementById(id);if(el)el.addEventListener(key==='query'?'input':'change',()=>{filter[key]=el.value;document.getElementById('catalog-results').innerHTML=catalogCards();bindCompare();});}document.getElementById('workspace-form')?.addEventListener('submit',e=>{e.preventDefault();model.role=new FormData(e.target).get('role');audit('Opened '+model.role+' demo workspace');location.hash=model.role==='learner'?'dashboard':model.role;});document.getElementById('studio-form')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target),id=f.get('id')||'module-'+crypto.randomUUID();const d={id,published:false};for(const [key]of studioFields){d[key]=String(f.get(key)).trim();if(!d[key])return toast('Complete every field before saving.');}const i=model.drafts.findIndex(x=>x.id===id);i<0?model.drafts.push(d):model.drafts.splice(i,1,d);audit('Saved module draft: '+d.title);location.hash='studio';render();toast('Module draft saved on this browser.');});document.querySelectorAll('.grading-form').forEach(form=>form.onsubmit=e=>{e.preventDefault();const f=new FormData(form),scores={},maxes={correctness:40,structure:30,validation:20,explanation:10};for(const [key,max]of Object.entries(maxes)){const v=Number(f.get(key));if(!Number.isInteger(v)||v<0||v>max)return toast('Enter valid whole-number rubric scores.');scores[key]=v;}const feedback=String(f.get('feedback')).trim();if(!feedback)return toast('Add feedback for the learner.');const id=form.dataset.submission;model.reviews[id]={scores,total:Object.values(scores).reduce((a,b)=>a+b,0),feedback,time:new Date().toISOString()};audit('Reviewed '+id+' and returned feedback');render();toast('Review saved. Feedback is now in the learner gradebook.');});document.getElementById('capstone-form')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);model.capstone={name:String(f.get('name')).trim(),notes:String(f.get('notes')).trim()};delete model.reviews.capstone;audit('Submitted capstone description for demo review');render();toast('Demo capstone submitted.');});document.querySelectorAll('[data-milestone]').forEach(el=>el.onchange=()=>{el.checked?state.completed.add('milestone-'+el.dataset.milestone):state.completed.delete('milestone-'+el.dataset.milestone);persist();});document.querySelectorAll('[data-proctor]').forEach(el=>el.onchange=()=>{const id=Number(el.dataset.proctor);model.readiness=model.readiness.filter(x=>x!==id);if(el.checked)model.readiness.push(id);persist();});document.querySelectorAll('[data-visibility]').forEach(el=>el.onchange=()=>{const id=Number(el.dataset.visibility);model.hidden=model.hidden.filter(x=>x!==id);if(!el.checked)model.hidden.push(id);audit((el.checked?'Show':'Hide')+' program '+id+' in local catalog');toast('Local preview visibility updated.');});}
document.addEventListener('click',e=>{let el=e.target.closest('[data-enroll],[data-syllabus],[data-publish],[data-authored-complete],[data-support-topic],[data-integrated]');if(!el)return;if(el.dataset.enroll){const id=Number(el.dataset.enroll);if(!findProgram(id))return;if(!model.enrollments.includes(id))model.enrollments.push(id);audit('Added program '+id+' to demo learning');render();toast('Added to My courses. No enrollment or payment created.');}if(el.dataset.syllabus){const p=findProgram(el.dataset.syllabus);download('scholarion-program-'+p.id+'-outline.txt',`SCHOLARION AI ACADEMY\nProgram ${p.id}: ${p.title}\nDRAFT CURRICULUM\n\n${p.summary}\nDuration: ${p.length}\n${p.format}\n\n${p.weeks?.map(([n,t])=>n+'. '+t).join('\n')||p.specification||'Detailed curriculum pending.'}\n\nCAPSTONE\n${p.capstone}\n\nNon-credit professional learning. Not an issued credential.`);}if(el.dataset.publish){const d=model.drafts.find(x=>x.id===el.dataset.publish);if(!d||studioFields.some(([k])=>!d[k]?.trim()))return toast('Complete all module fields first.');d.published=!d.published;audit((d.published?'Published':'Unpublished')+' demo module: '+d.title);render();}if(el.dataset.authoredComplete){state.completed.add(el.dataset.authoredComplete);audit('Reviewed authored module');render();}if(el.dataset.supportTopic){const answers={Webcam:'Position the camera so your face, hands, and workspace can remain visible. Check your assessment’s actual policy before test day.',ID:'The supplied sample policy requires a current government-issued photo ID. If yours is expired, seek support before test day. Do not upload ID here.',Devices:'Remove unapproved devices and smart glasses. Avoid music. Confirm permitted equipment with the assessment provider.',Highlighting:'Use highlighting only when available as an approved tool in the assessment platform. Do not copy or paste assessment content.',Accessibility:'Arrange accommodation review in advance if assistive technology conflicts with the setup. This helper cannot approve exceptions and does not need a diagnosis.'};document.getElementById('support-answer').textContent=answers[el.dataset.supportTopic];}switch(el.dataset.integrated){case'catalog':location.hash='catalog';break;case'clear-filters':filter={query:'',track:'All',format:'All',level:'All'};render();break;case'compare':if(compare.size<2)return toast('Select two or three programs to compare.');modal('Compare programs',`<div class="comparison">${[...compare].map(findProgram).map(p=>`<section><h3>${esc(p.title)}</h3><p>${esc(p.length)} · ${esc(p.format)}</p><p>${esc(p.coding)}</p><p><b>Capstone</b><br>${esc(p.capstone)}</p>${btn('Program details','#program/'+p.id,true)}</section>`).join('')}</div>`);break;case'save-readiness':audit('Saved self-reported readiness: '+model.readiness.length+'/8');document.getElementById('readiness-status').innerHTML=`<div class="feedback">${model.readiness.length} of 8 self-reported checks saved. This does not approve or schedule an assessment.</div>`;break;case'dataset':download('scholarion-synthetic-operations.csv','record_id,department,wait_minutes,visit_month\nS001,Operations A,12,2026-01\nS002,Operations B,18,2026-01\nS003,Operations A,,2026-02\nS004,Operations B,24,2026-02\nS005,Operations A,-1,2026-03\nS006,Operations B,15,2026-03\n','text/csv');break;case'export':persist();download('scholarion-local-demo.json',JSON.stringify(model,null,2),'application/json');break;case'reset-prompt':modal('Reset local demo?','<p>This clears authored modules, selections, submissions, reviews, and practice progress from this browser. Export your demo data first if you need a copy.</p><button class="button" data-integrated="reset-confirm">Reset this browser’s demo</button>');break;case'reset-confirm':localStorage.removeItem(STORE_KEY);location.hash='home';location.reload();break;}});
// Preserve existing lesson, quiz, lab, and project actions after their handlers run.
document.addEventListener('input',()=>persist());
document.addEventListener('change',()=>persist());
document.addEventListener('click',e=>{if(e.target.closest('[data-action]'))setTimeout(persist,0);});
document.addEventListener('submit',e=>{if(e.target.id==='project-form'){delete model.reviews['mini-project'];setTimeout(()=>audit('Updated mini project demo submission'),0);}else setTimeout(persist,0);});
window.addEventListener('hashchange',()=>persist());
const baseGradePage=grades;
grades=function(){return baseGradePage().replace('data-action="download-grades"','data-integrated="export-grades"');};
document.addEventListener('click',e=>{if(e.target.closest('[data-integrated="export-grades"]')){const rows=[['Activity','Type','Score','Feedback'],['Module 1 quiz','Sample quiz','18/20','Illustrative record'],['Lab 1','Sample lab','20/20','Illustrative record'],['Module 2 assignment','Sample assignment','26/30','Illustrative record'],['Module 2 quiz','Sample quiz','16/20','Illustrative record'],['Lab 2','Sample lab','18/20','Illustrative record'],['Module 3 project','Sample project','45/50','Illustrative record']];for(const [id,r]of Object.entries(model.reviews))rows.push([id,'Demo review',r.total+'/100',r.feedback]);const safeCell=s=>{s=String(s);if(/^[=+@-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};download('scholarion-demo-gradebook.csv',rows.map(r=>r.map(safeCell).join(',')).join('\r\n'),'text/csv');}});
render();


